!function(){"use strict";const PATH_MAIN_MODAL="~Areas/Caja/Pages/Shared/_ModalAddUpdate.cshtml",PATH_API="Caja/";let mS={};function cajaCtrl($scope,$injector){mS=$injector.get("mainService"),$scope.dataSearch={pageIndex:1,pageSize:1e3},$scope.initiload=function(){try{$scope.cajas=[],mS.getData("get","Caja/?json="+JSON.stringify($scope.dataSearch),null,!0).then(response=>{hideLoader(),"0"==response.code&&console.log(response),"1"==response.code&&($scope.cajas=JSON.parse(response.payload)||[])}).catch(error=>{hideLoader(),console.log(error)})}catch(error){hideLoader(),console.log(error)}},$scope.initiload()}app.controller("cajaCtrl",cajaCtrl),cajaCtrl.$inject=["$scope","$injector"]}(window.angular);